                even[i] = even[i - 1];
            } else {
                odd[i] = odd[i - 1];
                even[i] = even[i - 1] + 1;
            }
        }

        int prev = 0;
        PriorityQueue<Integer> cost = new PriorityQueue<>();
        for (int i = 1; i < n; i++) {
