#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }

    std::vector<int> odd(n + 1, 0);
    std::vector<int> even(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        if (a[i - 1] % 2 == 1) {
            odd[i] = odd[i - 1] + 1;
            even[i] = even[i - 1];
        } else {
            odd[i] = odd[i - 1];
            even[i] = even[i - 1] + 1;
        }
    }

    int prev = 0;
    std::priority_queue<int, std::vector<int>, std::greater<int>> cost;
    for (int i = 1; i < n; ++i) {
        int oc = odd[i] - odd[prev];
        int ec = even[i] - even[prev];
        if (oc == ec) {
            cost.push(std::abs(a[i] - a[i - 1]));
            prev = i;
        }
    }

    int sum = 0;
    int count = 0;
    while (!cost.empty() && sum + cost.top() <= b) {
        sum += cost.top();
        cost.pop();
        ++count;
    }

    std::cout << count << std::endl;
    return 0;
}
